return [=[
:root{color-scheme:light dark;--page-bg: #d6d6d6;--top-bg: whitesmoke;--top-border: #b1afaf;--top-shadow: rgba(0, 0, 0, .15);--footer-fg: #838383;--button-bg: #8aa8cf;--button-hover-bg: #9cb5d6;--button-fg: #294364;--result-bg: white;--result-fg: #444;--result-border: silver;--result-shadow: rgba(0, 0, 0, .15);--muted-fg: #888;--hover-bg: #eee;--value-string: #648164;--value-boolean: #664b66;--value-number: #5076a0;--queries-bg: #ddd;--queries-border: white;--queries-header-bg: #c4c4c4;--queries-header-border: #b4b4b4;--error-bg: rgba(194, 83, 83, .08);--error-border: #c25353;--error-fg: #a73b3b}@media(prefers-color-scheme:dark){:root{--page-bg: #1b1b1b;--top-bg: #262626;--top-border: #111;--top-shadow: rgba(0, 0, 0, .5);--footer-fg: #777;--button-bg: #3d5270;--button-hover-bg: #4a6285;--button-fg: #dbe6f5;--result-bg: #262626;--result-fg: #ddd;--result-border: #3a3a3a;--result-shadow: rgba(0, 0, 0, .4);--muted-fg: #999;--hover-bg: #333;--value-string: #9fcf9f;--value-boolean: #d4a0d4;--value-number: #8fb4e0;--queries-bg: #1f1f1f;--queries-border: #3a3a3a;--queries-header-bg: #303030;--queries-header-border: #3a3a3a;--error-bg: rgba(194, 83, 83, .12);--error-border: #c25353;--error-fg: #eb9a9a}}body{font-family:sans-serif;font-size:16px;background:var(--page-bg);margin:0}#editor .editor_top{background:var(--top-bg);padding:20px;border-bottom:1px solid var(--top-border);box-shadow:0 -2px 4px 4px var(--top-shadow)}#editor .cm-editor{font-size:14px}#editor .log{padding:0 20px}#editor .footer{text-align:center;margin:10px;font-size:12px;color:var(--footer-fg)}#editor .buttons_top{display:flex;align-items:center;gap:10px;margin-bottom:7px}#editor .buttons_top button,#editor .buttons_top select{font-size:16px;background:var(--button-bg);color:var(--button-fg);border:0;padding:5px 10px;border-radius:4px;transition:background .2s ease-in-out}:is(#editor .buttons_top button,#editor .buttons_top select):hover{background:var(--button-hover-bg)}#editor .buttons_top button:active{position:relative;top:1px}#editor .buttons_top button:disabled{opacity:.6;cursor:progress}#editor .buttons_top .clear_log_btn{margin-left:auto}#editor .status{background:#7bb87b;text-shadow:1px 1px 1px #488548;color:#fff;padding:4px 8px;white-space:pre-wrap;transition:background .2s ease-in-out}#editor .status.error{background:#c25353;text-shadow:1px 1px 1px #a73b3b}#editor .status.loading{background:#e9d674;text-shadow:1px 1px 1px #a9921b}#editor .result{border:1px solid var(--result-border);background:var(--result-bg);box-shadow:1px 1px 4px var(--result-shadow);color:var(--result-fg);margin:10px 0}#editor .result .result_code{margin:0;padding:5px 10px;max-height:10em;overflow:auto;cursor:pointer;color:var(--muted-fg);border-bottom:1px dashed var(--result-border)}#editor .result .result_code:before{content:attr(data-lang);float:right;font-family:sans-serif;font-size:11px}#editor .result .result_code:hover{background:var(--hover-bg)}#editor .result .no_output{font-style:italic;color:var(--muted-fg);padding:10px}#editor .result .line{font-family:monospace}#editor .result .line.returns:before{content:"\21d2";display:inline-block;vertical-align:top;padding:10px 0 0 10px;color:var(--muted-fg)}#editor .result .result_error{margin:5px;padding:5px 10px;background:var(--error-bg);border-left:3px solid var(--error-border)}#editor .result .result_error pre{margin:0;white-space:pre-wrap}#editor .result .result_error .message{color:var(--error-fg)}#editor .result .result_error summary{cursor:pointer;margin-top:5px;font-size:13px;color:var(--muted-fg)}#editor .result .result_error .traceback{font-size:12px;margin-top:5px}#editor .result .time{text-align:right;font-size:11px;padding:2px 6px;color:var(--muted-fg)}#editor .result .value{margin:5px;padding:5px;display:inline-block;vertical-align:top}#editor .result .value.string{color:var(--value-string)}#editor .result .value.string:before,#editor .result .value.string:after{font-weight:700;content:'"'}#editor .result .value.string.key:before{content:""}#editor .result .value.boolean{color:var(--value-boolean)}#editor .result .value.number{color:var(--value-number)}#editor .result .value.function,#editor .result .value.recursion,#editor .result .value.metatable{color:var(--muted-fg);font-style:italic}#editor .result .value.recursion:before{content:"(recursion) ";font-style:normal;font-weight:700;font-size:14px}#editor .result .value.key{margin-right:0;padding-right:0}#editor .result .value.key:after{content:": ";font-style:normal;font-weight:700;color:var(--result-fg)}#editor .result .value:hover{background:var(--hover-bg);border-radius:3px}#editor .result .value.expanded{border-left:1px dashed var(--result-border);margin-left:10px;padding:0}#editor .result .value.expanded:hover{background:var(--result-bg)}#editor .result .tuple{margin-left:10px}#editor .result .tuple>.value{margin-top:0;margin-bottom:0}#editor .result .expandable{cursor:pointer;font-weight:700}#editor .result .closable{font-weight:700;vertical-align:top;display:inline-block;cursor:pointer;padding:5px;margin:5px}#editor .result .closable:first-child{margin-bottom:0}#editor .result .closable:last-child{margin-top:0}#editor .result .closable:hover{background:var(--hover-bg);border-radius:3px}#editor .result .queries{font-family:monospace;background:var(--queries-bg);border:1px solid var(--queries-border)}#editor .result .queries:before{content:"Queries:";display:block;background:var(--queries-header-bg);border-bottom:1px solid var(--queries-header-border);font-size:12px;padding:5px;font-family:sans-serif}#editor .result .queries .query{display:flex;gap:10px;padding:5px}#editor .result .queries .query .sql{flex:1;white-space:pre-wrap}#editor .result .queries .query .duration{white-space:nowrap;color:var(--muted-fg)}
]=]
